package com.wiseway.web;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(ApiController.class) class ApiControllerTest { @Autowired MockMvc mvc; @MockBean com.wiseway.service.RecommendationService rec; @MockBean com.wiseway.service.SavedRouteService routes; @MockBean com.wiseway.service.ExpenseService expenses; @MockBean com.wiseway.service.GeocodingService geocoding; @Test void blankOriginIsRejected() throws Exception {mvc.perform(post("/api/v1/recommendations/compare").contentType(MediaType.APPLICATION_JSON).content("{\"origin\":\"\",\"destination\":\"Campus\"}" )).andExpect(status().isBadRequest());}}
